[CmdletBinding()]param([string]$RepositoryRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop';$prep=Join-Path $RepositoryRoot 'Modules\ADHealth\Prepare-MSADPTADHealthEvidence-v1.2.0.ps1';$source=Join-Path $RepositoryRoot 'Tests\Fixtures\ADHealthPreparation';$temp=Join-Path ([IO.Path]::GetTempPath()) ('MSADPT-ADHealth-v120-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $temp|Out-Null
try{$r=& $prep -SourceEvidenceRoot $source -OutputRoot $temp;if($r.Status-ne'Succeeded'){throw 'Preparation failed'};if($r.MappedFileCount-ne5){throw "Expected 5 mapped files, got $($r.MappedFileCount)"};if($r.UnmappedFileCount-ne1){throw "Expected one unmapped file, got $($r.UnmappedFileCount)"};if($r.HashVerifiedCount-ne5){throw 'Not all staged evidence hashes were verified'};if($r.ExpectedTargetCount-ne2){throw "Expected two derived targets, got $($r.ExpectedTargetCount)"};if($r.AssessmentStatus-ne'Succeeded'){throw 'Offline assessment was not invoked successfully'};foreach($name in @('ADHealth-Staging-Mappings.csv','ADHealth-Staging-Mappings.json','ExpectedTargets.csv','ADHealth-Preparation-Summary.json')){if(-not(Test-Path -LiteralPath (Join-Path $temp $name))){throw "Missing output: $name"}};if(-not(Test-Path -LiteralPath (Join-Path $temp 'Assessment\MSADPT-AD-Health.html'))){throw 'Assessment HTML missing'};$map=Import-Csv -LiteralPath (Join-Path $temp 'ADHealth-Staging-Mappings.csv');if(@($map|Where-Object{$_.SourceFileName-eq'random-notes.txt'-and$_.Mapped-eq'False'}).Count-ne1){throw 'Ambiguous file was not retained as unmapped'}
[pscustomobject]@{Status='Passed';TestVersion='1.2.0';SourceFileCount=$r.SourceFileCount;MappedFileCount=$r.MappedFileCount;UnmappedFileCount=$r.UnmappedFileCount;HashIntegrityValidated=$true;ExpectedTargetsDerived=$true;OfflineAssessmentInvoked=$true;AmbiguousEvidenceUnmapped=$true;NetworkActivity='None';ActiveDirectoryQueries='None';RemoteChanges='None'}
}finally{Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue}
